package com.paytrace.incident;
import com.paytrace.integrity.*; import com.paytrace.payment.*; import com.paytrace.timeline.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.*;
@Service public class IncidentDetector { private final PaymentEventRepository events; private final CanonicalStateResolver resolver; private final IntegrityEngine integrity; private final IncidentRepository repository; public IncidentDetector(PaymentEventRepository e,CanonicalStateResolver r,IntegrityEngine i,IncidentRepository repo){events=e;resolver=r;integrity=i;repository=repo;}
 @Transactional public List<Incident> investigate(UUID paymentId){var all=events.findByPaymentIdOrderByOccurredAtAsc(paymentId);var resolution=resolver.resolve(all);var invariants=integrity.evaluate(paymentId);var incidents=new ArrayList<Incident>();if(all.stream().anyMatch(e->e.eventType()==PaymentEventType.WEBHOOK_DUPLICATE))incidents.add(newIncident(paymentId,IncidentType.WEBHOOK_DUPLICATE,Severity.LOW,List.of("Stable provider event ID was received more than once"),List.of("WEBHOOK")));if(resolution.anomalies().contains("OUT_OF_ORDER_DELIVERY"))incidents.add(newIncident(paymentId,IncidentType.WEBHOOK_OUT_OF_ORDER,Severity.LOW,List.of("Received ordering differs from occurredAt ordering"),List.of("WEBHOOK","TIMELINE")));for(var invariant:invariants)if(!invariant.passed())incidents.add(newIncident(paymentId,invariant.name().contains("Ledger")?IncidentType.LEDGER_IMBALANCE:IncidentType.PROVIDER_STATE_MISMATCH,Severity.HIGH,List.of(invariant.evidence()),List.of("INTEGRITY")));if(all.stream().anyMatch(e->e.eventType()==PaymentEventType.PROVIDER_TIMEOUT)&&resolution.canonicalState()==PaymentState.CAPTURED)incidents.add(newIncident(paymentId,IncidentType.AMBIGUOUS_PAYMENT,Severity.HIGH,List.of("Merchant timeout and provider capture both present"),List.of("MERCHANT","PROVIDER")));if(incidents.isEmpty())incidents.add(newIncident(paymentId,IncidentType.NORMAL,Severity.INFO,List.of("No integrity violation evidence found"),List.of("PAYMENT")));repository.saveAll(incidents.stream().map(IncidentEntity::new).toList());return List.copyOf(incidents);}
 public List<Incident> list(UUID paymentId){return repository.findByPaymentId(paymentId).stream().map(IncidentEntity::view).toList();} private Incident newIncident(UUID paymentId,IncidentType type,Severity severity,List<String> evidence,List<String> components){return new Incident(UUID.randomUUID(),paymentId,type,severity,Instant.now(),evidence,components,List.of("Deterministic event and invariant evaluation"));}
}
